// Milestone 1: check that the URL is safe and authorized before any crawling.
// The n8n Code sandbox has no built-in URL parser, so we parse with a strict pattern.
// Every rejection carries a CODE plus a plain-English reason, so logs are easy to read.
const results = [];
for (const item of $input.all()) {
  const cfg = item.json;
  const raw = String(cfg.targetUrl === undefined || cfg.targetUrl === null ? '' : cfg.targetUrl).trim();
  const allowed = String(cfg.allowedDomains || '')
    .split(',')
    .map(s => s.trim().toLowerCase().replace(/^www\./, ''))
    .filter(Boolean);
  const out = {
    inputUrl: raw,
    isValid: false,
    normalizedUrl: '',
    hostname: '',
    reason: '',
    allowedDomains: allowed.join(','),
    maxPages: cfg.maxPages,
    checkedAt: new Date().toISOString()
  };
  const fail = (r) => { out.reason = r; results.push({ json: out }); };

  if (allowed.length === 0) { fail('NO_ALLOWLIST: Agent Config has no allowed domains, so nothing can be audited'); continue; }
  if (!raw) { fail('EMPTY_URL: No URL was provided'); continue; }
  if (raw.length > 2048) { fail('URL_TOO_LONG: URL is longer than 2048 characters'); continue; }
  if (/\s/.test(raw)) { fail('INVALID_FORMAT: Web addresses cannot contain spaces'); continue; }

  let candidate = raw;
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(candidate)) candidate = 'https://' + candidate;

  const m = candidate.match(/^([a-z][a-z0-9+.-]*):\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) { fail('INVALID_FORMAT: This is not a valid web address'); continue; }
  const protocol = m[1].toLowerCase();
  const authority = m[2];
  const path = m[3] || '/';
  const search = m[4] || '';

  if (protocol !== 'http' && protocol !== 'https') { fail('UNSUPPORTED_PROTOCOL: Only http and https are allowed (got ' + protocol + ')'); continue; }
  if (authority.includes('@')) { fail('CREDENTIALS_IN_URL: URLs with a username or password are not allowed'); continue; }
  if (authority.startsWith('[')) { fail('IP_ADDRESS_NOT_ALLOWED: Use a domain name, not an IP address'); continue; }

  const hp = authority.match(/^([^:]+)(?::(\d*))?$/);
  if (!hp) { fail('INVALID_FORMAT: The address has an invalid host or port'); continue; }
  const host = hp[1].toLowerCase().replace(/\.$/, '');
  const port = hp[2] || '';
  out.hostname = host;

  if (!/^[a-z0-9.-]+$/.test(host) || host.startsWith('.') || host.includes('..')) { fail('INVALID_FORMAT: The domain name contains characters that are not allowed'); continue; }
  if (/^\d+(\.\d+){3}$/.test(host)) { fail('IP_ADDRESS_NOT_ALLOWED: Use a domain name, not an IP address'); continue; }
  if (host === 'localhost' || /\.(localhost|local|internal|lan|home)$/.test(host) || !host.includes('.')) { fail('PRIVATE_HOST_BLOCKED: Local or internal addresses are blocked to protect your server'); continue; }
  if (port && port !== '80' && port !== '443') { fail('NON_STANDARD_PORT: Only the normal web ports are allowed (got ' + port + ')'); continue; }

  const bare = host.replace(/^www\./, '');
  const isAllowed = allowed.some(d => bare === d || bare.endsWith('.' + d));
  if (!isAllowed) { fail('NOT_IN_ALLOWLIST: ' + host + ' is not an authorized website (' + allowed.join(', ') + ')'); continue; }

  out.normalizedUrl = protocol + '://' + host + (port ? ':' + port : '') + (path.startsWith('/') ? path : '/' + path) + search;
  out.isValid = true;
  out.reason = 'OK';
  results.push({ json: out });
}
return results;

// Milestone 2a: read robots.txt and decide what we are allowed to crawl.
// 200 = follow the file. 4xx = no robots.txt, everything allowed.
// 5xx or network error = we cannot know the rules, so we crawl nothing (safest, same as Google).
const cfg = $('Ready for Crawl').first().json;
const res = $input.first().json;
const UA_TOKEN = 'seogrowthagent';
const origin = cfg.normalizedUrl.match(/^https?:\/\/[^\/?#]+/i)[0];
const status = Number(res.statusCode || 0);
const body = typeof res.data === 'string' ? res.data : '';

let mode;
if (res.error || !status) mode = 'UNREACHABLE_BLOCK_ALL';
else if (status >= 200 && status < 300) mode = 'PARSED';
else if (status >= 400 && status < 500) mode = 'NOT_FOUND_ALLOW_ALL';
else mode = 'UNREACHABLE_BLOCK_ALL';

const groups = [];
const sitemaps = [];
let current = null;
let lastWasAgent = false;
if (mode === 'PARSED') {
  for (let line of body.split(/\r?\n/)) {
    line = line.replace(/#.*$/, '').trim();
    if (!line) continue;
    const idx = line.indexOf(':');
    if (idx < 0) continue;
    const key = line.slice(0, idx).trim().toLowerCase();
    const val = line.slice(idx + 1).trim();
    if (key === 'user-agent') {
      if (!current || !lastWasAgent) { current = { agents: [], rules: [], crawlDelay: null }; groups.push(current); }
      current.agents.push(val.toLowerCase());
      lastWasAgent = true;
      continue;
    }
    lastWasAgent = false;
    if (key === 'sitemap') { sitemaps.push(val); continue; }
    if (!current) continue;
    if ((key === 'allow' || key === 'disallow') && val) current.rules.push({ type: key, path: val });
    else if (key === 'crawl-delay') { const n = parseFloat(val); if (!isNaN(n)) current.crawlDelay = n; }
  }
}
let chosen = groups.filter(g => g.agents.some(a => a !== '*' && UA_TOKEN.includes(a)));
const matchedGroup = chosen.length ? 'specific' : 'wildcard';
if (!chosen.length) chosen = groups.filter(g => g.agents.includes('*'));
const rules = chosen.reduce((acc, g) => acc.concat(g.rules), []);
const delays = chosen.map(g => g.crawlDelay).filter(d => d !== null);
const crawlDelaySec = delays.length ? delays[0] : null;
const delayMs = Math.min(10000, Math.max(1500, Math.round((crawlDelaySec || 0) * 1000)));

function toRegex(p) {
  let r = p.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
  if (r.endsWith('\\$')) r = r.slice(0, -2) + '$';
  return new RegExp('^' + r);
}
function isAllowed(pathWithQuery) {
  if (mode === 'UNREACHABLE_BLOCK_ALL') return false;
  let best = null;
  for (const r of rules) {
    if (toRegex(r.path).test(pathWithQuery)) {
      if (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.type === 'allow')) best = r;
    }
  }
  return !best || best.type === 'allow';
}
const startPath = cfg.normalizedUrl.slice(origin.length) || '/';
return [{ json: {
  runId: 'run_' + $execution.id,
  targetUrl: cfg.normalizedUrl,
  hostname: cfg.hostname,
  origin,
  maxPages: Number(cfg.maxPages) || 20,
  robotsUrl: origin + '/robots.txt',
  robotsStatusCode: status,
  robotsMode: mode,
  robotsGroupUsed: groups.length ? matchedGroup : 'none',
  robotsRules: rules,
  sitemaps,
  crawlDelaySec,
  delayMs,
  startAllowed: isAllowed(startPath),
  startPath
} }];

// Milestone 2.1b: choose which pages to audit (at most maxPages).
// 1. The start page is always first.
// 2. Pages from the sitemap, spread across site sections (products, categories, blog...) so a
//    20-page sample covers the whole site instead of only the first 20 sitemap entries.
// 3. If there is room left (or no sitemap), links found on the start page.
// Every candidate must be on the same site, look like an HTML page, and be allowed by robots.txt.
function planCrawl(ctx, startRes, sitemapFiles, targets) {
  const host = ctx.hostname.replace(/^www\./, '');
  const maxPages = ctx.maxPages;
  const rules = ctx.robotsRules || [];
  const toRegex = p => {
    let r = p.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
    if (r.endsWith('\\$')) r = r.slice(0, -2) + '$';
    return new RegExp('^' + r);
  };
  const isAllowed = pathQ => {
    if (ctx.robotsMode === 'UNREACHABLE_BLOCK_ALL') return false;
    let best = null;
    for (const r of rules) if (toRegex(r.path).test(pathQ)) {
      if (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.type === 'allow')) best = r;
    }
    return !best || best.type === 'allow';
  };
  const resolve = (href, base) => {
    href = String(href || '').trim().replace(/&amp;/g, '&');
    if (!href || href.startsWith('#')) return null;
    if (/^[a-z][a-z0-9+.-]*:/i.test(href) && !/^https?:/i.test(href)) return null;
    href = href.split('#')[0];
    if (!href) return null;
    let abs;
    if (/^https?:\/\//i.test(href)) abs = href;
    else if (href.startsWith('//')) abs = base.split('//')[0] + href;
    else {
      const bm = base.match(/^(https?:\/\/[^\/?#]+)([^?#]*)/i);
      const bPath = bm[2] || '/';
      abs = bm[1] + (href.startsWith('/') ? href : href.startsWith('?') ? bPath + href : bPath.replace(/[^\/]*$/, '') + href);
    }
    const m = abs.match(/^(https?:\/\/[^\/?#]+)([^?#]*)(\?[^#]*)?/i);
    if (!m) return null;
    const segs = [];
    for (const s of (m[2] || '/').split('/')) { if (s === '..') { if (segs.length > 1) segs.pop(); } else if (s !== '.') segs.push(s); }
    let p = segs.join('/'); if (!p.startsWith('/')) p = '/' + p;
    return m[1].toLowerCase() + p + (m[3] || '');
  };
  const stats = { startPageStatus: Number(startRes.statusCode || 0), sitemapSource: '', sitemapFilesRead: 0, sitemapUrlsFound: 0,
    fromSitemap: 0, fromLinks: 0, linksFound: 0, offSite: 0, nonHtml: 0, duplicates: 0, blockedByRobots: 0, overPageLimit: 0 };
  const t0 = targets[0] || {};
  stats.sitemapSource = t0.rootSitemapType === 'index' ? 'index' : (t0.rootSitemapDeclared ? 'robots.txt' : '/sitemap.xml');
  const folderTarget = targets.find(t => t.rootSitemapType === 'folder');
  stats.rootSitemapUrl = t0.rootSitemapUrl || '';
  stats.folderSitemapUrl = folderTarget ? folderTarget.sitemapUrl : '';
  stats.rootSitemapStatus = t0.rootSitemapStatus || 0;

  const startUrl = resolve(ctx.targetUrl, ctx.targetUrl);
  // Audit scope: the folder of the start URL. For example.com/ that is the whole site; for
  // user.github.io/shop/ only pages under /shop/ are audited, never other projects on the domain.
  const scope = startUrl.replace(/[?#].*$/, '').replace(/[^\/]*$/, '').replace(/^https?:\/\/(www\.)?/i, '');
  stats.scope = scope;
  const seen = new Set([startUrl]);
  const planned = [{ url: startUrl, source: 'start' }];
  function accept(u) {
    if (!u) return null;
    const h = u.replace(/^https?:\/\//i, '').split(/[\/?#:]/)[0].replace(/^www\./, '');
    if (h !== host || !u.replace(/^https?:\/\/(www\.)?/i, '').startsWith(scope)) { stats.offSite++; return null; }
    if (/\.(jpe?g|png|gif|svg|webp|avif|ico|pdf|zip|css|js|xml|txt|json|mp4|mp3|woff2?)(\?|$)/i.test(u)) { stats.nonHtml++; return null; }
    if (seen.has(u)) { stats.duplicates++; return null; }
    seen.add(u);
    const pathQ = u.replace(/^https?:\/\/[^\/]+/i, '') || '/';
    if (!isAllowed(pathQ)) { stats.blockedByRobots++; return null; }
    return u;
  }

  // Sitemap URLs, grouped by first path segment, then taken round-robin.
  const groups = new Map();
  for (const f of sitemapFiles) {
    const st = Number(f.statusCode || 0);
    const body = typeof f.data === 'string' ? f.data : (typeof f.body === 'string' ? f.body : '');
    if (st < 200 || st >= 300 || !/<urlset[\s>]/i.test(body)) continue;
    stats.sitemapFilesRead++;
    if (folderTarget && sitemapFiles.indexOf(f) === targets.indexOf(folderTarget)) stats.sitemapSource = 'folder';
    for (const m of body.matchAll(/<url>[\s\S]*?<loc>([^<]+)<\/loc>/gi)) {
      stats.sitemapUrlsFound++;
      const u = accept(resolve(m[1], ctx.targetUrl));
      if (!u) continue;
      // Section = first folder below the audit scope (products, shop, journal...).
      const seg = (u.replace(/^https?:\/\/(www\.)?/i, '').slice(scope.length).split('/')[0] || '(root)');
      if (!groups.has(seg)) groups.set(seg, []);
      groups.get(seg).push(u);
    }
  }
  const queues = [...groups.values()];
  let added = true;
  while (planned.length < maxPages && added) {
    added = false;
    for (const q of queues) { if (planned.length >= maxPages) break; const u = q.shift(); if (u) { planned.push({ url: u, source: 'sitemap' }); stats.fromSitemap++; added = true; } }
  }
  stats.overPageLimit += queues.reduce((s, q) => s + q.length, 0);

  // Links on the start page fill any remaining room.
  const html = typeof startRes.data === 'string' ? startRes.data : '';
  for (const m of html.matchAll(/<a\b[^>]*?\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi)) {
    stats.linksFound++;
    const u = accept(resolve(m[1] || m[2] || m[3] || '', startUrl));
    if (!u) continue;
    if (planned.length < maxPages) { planned.push({ url: u, source: 'link' }); stats.fromLinks++; } else stats.overPageLimit++;
  }
  return planned.map((p, i) => ({ runId: ctx.runId, url: p.url, discoveredVia: p.source, crawlOrder: i + 1, plannedPages: planned.length, delayMs: ctx.delayMs, discovery: stats }));
}

const ctx = $('Parse robots.txt').first().json;
const files = $('Fetch Sitemap Files').all().map(i => i.json);
const targets = $('Sitemap Targets').all().map(i => i.json);
return planCrawl(ctx, $input.first().json, files, targets).map(j => ({ json: j }));

// Milestone 2c: one clean record per page. The raw HTML is kept for Milestone 3 (extraction)
// but will NOT be written to Google Sheets.
const ctx = $('Parse robots.txt').first().json;
const plan = $('Plan Crawl List').all();
const collectedAt = new Date().toISOString();
return $input.all().map((it, i) => {
  const p = plan[i] ? plan[i].json : {};
  const r = it.json;
  const headers = r.headers || {};
  const ct = String(headers['content-type'] || '');
  const html = typeof r.data === 'string' ? r.data : '';
  const status = Number(r.statusCode || 0);
  const err = r.error ? String(r.error.message || r.error) : '';
  return { json: {
    runId: ctx.runId,
    auditTarget: ctx.targetUrl,
    url: p.url || '',
    crawlOrder: p.crawlOrder || i + 1,
    fetchStatus: err ? 'NETWORK_ERROR' : (status >= 200 && status < 300 ? 'OK' : 'HTTP_' + status),
    statusCode: status,
    contentType: ct,
    isHtml: /text\/html/i.test(ct),
    htmlBytes: html.length,
    serverDate: String(headers['date'] || ''),
    lastModified: String(headers['last-modified'] || ''),
    fetchError: err,
    collectedAt,
    html
  } };
});

// Milestone 3: extract SEO data from each collected page.
// Pure text parsing (no browser), so it sees exactly what a search engine's first fetch sees.
// The raw HTML is dropped at the end so it never reaches Google Sheets.

function decode(s) {
  return String(s || '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}
function clean(s) { return decode(String(s || '').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim(); }
function attr(tag, name) {
  const m = tag.match(new RegExp('\\s' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i'));
  return m ? decode(m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3])) : null;
}
function tags(html, name) { return html.match(new RegExp('<' + name + '\\b[^>]*>', 'gi')) || []; }
function blocks(html, name) {
  const out = []; const re = new RegExp('<' + name + '\\b[^>]*>([\\s\\S]*?)</' + name + '\\s*>', 'gi'); let m;
  while ((m = re.exec(html)) !== null) out.push(clean(m[1]));
  return out;
}
function resolve(href, base) {
  href = String(href || '').trim();
  if (!href || href.startsWith('#')) return null;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href) && !/^https?:/i.test(href)) return null;
  href = href.split('#')[0];
  if (!href) return null;
  let abs;
  if (/^https?:\/\//i.test(href)) abs = href;
  else if (href.startsWith('//')) abs = base.split('//')[0] + href;
  else {
    const bm = base.match(/^(https?:\/\/[^\/?#]+)([^?#]*)/i);
    const bPath = bm[2] || '/';
    let path;
    if (href.startsWith('/')) path = href;
    else if (href.startsWith('?')) path = bPath + href;
    else path = bPath.replace(/[^\/]*$/, '') + href;
    abs = bm[1] + path;
  }
  const m = abs.match(/^(https?:\/\/[^\/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const segs = [];
  for (const s of (m[2] || '/').split('/')) {
    if (s === '..') { if (segs.length > 1) segs.pop(); }
    else if (s !== '.') segs.push(s);
  }
  let p = segs.join('/');
  if (!p.startsWith('/')) p = '/' + p;
  return m[1].toLowerCase() + p + (m[3] || '');
}
function hash(s) { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(16); }
function metaByName(metas, key, val) {
  for (const t of metas) { const v = attr(t, key); if (v && v.toLowerCase() === val) return attr(t, 'content'); }
  return null;
}

function extractPage(p) {
  const base = {
    runId: p.runId, auditTarget: p.auditTarget, url: p.url, crawlOrder: p.crawlOrder,
    fetchStatus: p.fetchStatus, statusCode: p.statusCode, contentType: p.contentType, htmlBytes: p.htmlBytes
  };
  if (p.fetchStatus !== 'OK' || !p.isHtml || !p.html) {
    return Object.assign(base, { extractionStatus: p.fetchStatus !== 'OK' ? 'SKIPPED_FETCH_FAILED' : 'SKIPPED_NOT_HTML' });
  }
  const raw = p.html;
  // Remove comments, scripts, styles, templates, noscript before reading content.
  const html = raw.replace(/<!--[\s\S]*?-->/g, '');
  const headM = html.match(/<head\b[^>]*>([\s\S]*?)<\/head\s*>/i);
  const head = headM ? headM[1] : html;
  const body = html.replace(/<(script|style|template|noscript|svg)\b[\s\S]*?<\/\1\s*>/gi, ' ');

  const titles = blocks(head, 'title');
  const title = titles[0] || '';
  const metas = tags(head, 'meta');
  // Trim: a description of only spaces/newlines is treated as empty (it shows nothing in Google).
  const mdRaw = metaByName(metas, 'name', 'description');
  const metaDescription = mdRaw === null ? null : mdRaw.replace(/\s+/g, ' ').trim();
  const metaRobots = metaByName(metas, 'name', 'robots');
  const viewport = metaByName(metas, 'name', 'viewport');
  const ogTitle = metaByName(metas, 'property', 'og:title');
  const ogDescription = metaByName(metas, 'property', 'og:description');
  const ogImage = metaByName(metas, 'property', 'og:image');
  const descCount = metas.filter(t => (attr(t, 'name') || '').toLowerCase() === 'description').length;

  const linkTags = tags(head, 'link');
  const canonTags = linkTags.filter(t => (attr(t, 'rel') || '').toLowerCase().split(/\s+/).includes('canonical'));
  const canonicalRaw = canonTags.length ? (attr(canonTags[0], 'href') || '') : '';
  const canonicalUrl = canonicalRaw ? (resolve(canonicalRaw, p.url) || '') : '';
  const hreflangCount = linkTags.filter(t => attr(t, 'hreflang')).length;
  const htmlTag = (html.match(/<html\b[^>]*>/i) || [''])[0];
  const lang = attr(htmlTag, 'lang') || '';

  const h1 = blocks(body, 'h1'), h2 = blocks(body, 'h2'), h3 = blocks(body, 'h3');

  const origin = p.url.match(/^https?:\/\/[^\/?#]+/i)[0].toLowerCase();
  const host = origin.replace(/^https?:\/\//, '').replace(/^www\./, '');
  let internal = 0, external = 0, nofollow = 0, emptyAnchor = 0, otherScheme = 0;
  const internalSet = new Set(), externalSet = new Set();
  const aRe = /<a\b([^>]*)>([\s\S]*?)<\/a\s*>/gi; let am;
  while ((am = aRe.exec(body)) !== null) {
    const t = '<a ' + am[1] + '>';
    const href = attr(t, 'href');
    if (href === null) continue;
    const rel = (attr(t, 'rel') || '').toLowerCase();
    if (/\bnofollow\b/.test(rel)) nofollow++;
    const text = clean(am[2]);
    const hasImgAlt = /<img\b[^>]*\salt\s*=\s*["'][^"']+["']/i.test(am[2]);
    if (!text && !hasImgAlt && !attr(t, 'aria-label') && !attr(t, 'title')) emptyAnchor++;
    const abs = resolve(href, p.url);
    if (!abs) { if (!href.trim().startsWith('#')) otherScheme++; continue; }
    const h = abs.replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].replace(/^www\./, '');
    if (h === host) { internal++; internalSet.add(abs); } else { external++; externalSet.add(abs); }
  }

  const imgs = tags(body, 'img');
  const imgNoAlt = imgs.filter(t => attr(t, 'alt') === null).length;
  const imgEmptyAlt = imgs.filter(t => { const a = attr(t, 'alt'); return a !== null && !a.trim(); }).length;

  const text = clean(body.replace(/<head\b[\s\S]*?<\/head\s*>/i, ' '));
  const words = text ? text.split(' ').filter(w => /[\p{L}\p{N}]/u.test(w)).length : 0;
  const scriptCount = (raw.match(/<script\b/gi) || []).length;
  const jsShell = /<div[^>]+id\s*=\s*["'](root|app|__next|__nuxt)["'][^>]*>\s*<\/div>/i.test(raw);
  const jsRenderedSuspected = words < 50 && (scriptCount >= 3 || jsShell);

  return Object.assign(base, {
    extractionStatus: 'OK',
    title, titleLength: title.length, titleTagCount: titles.length,
    metaDescription: metaDescription === null ? '' : metaDescription,
    metaDescriptionPresent: metaDescription !== null,
    metaDescriptionLength: metaDescription === null ? 0 : metaDescription.length,
    metaDescriptionTagCount: descCount,
    metaRobots: metaRobots || '',
    isNoindex: /\bnoindex\b/i.test(metaRobots || ''),
    canonicalRaw, canonicalUrl, canonicalTagCount: canonTags.length,
    canonicalIsSelf: canonicalUrl ? canonicalUrl === p.url : null,
    lang, viewportPresent: viewport !== null, hreflangCount,
    ogTitlePresent: ogTitle !== null, ogDescriptionPresent: ogDescription !== null, ogImagePresent: ogImage !== null,
    h1Count: h1.length, h1: h1.slice(0, 5), h2Count: h2.length, h2: h2.slice(0, 10), h3Count: h3.length, h3: h3.slice(0, 10),
    internalLinks: internal, uniqueInternalLinks: internalSet.size,
    externalLinks: external, uniqueExternalLinks: externalSet.size,
    nofollowLinks: nofollow, emptyAnchorLinks: emptyAnchor, nonHttpLinks: otherScheme,
    imageCount: imgs.length, imagesMissingAlt: imgNoAlt, imagesEmptyAlt: imgEmptyAlt,
    wordCount: words, scriptCount, jsRenderedSuspected,
    contentHash: hash(text)
  });
}

return $input.all().map(it => ({ json: extractPage(it.json) }));

// Milestone 4a: one PageSpeed test for mobile and one for desktop, on the audited start URL.
const ctx = $('Parse robots.txt').first().json;
