// sitemaps, preferring products, categories, pages and posts.
function sitemapTargets(ctx, res) {
  const rootUrl = (ctx.sitemaps && ctx.sitemaps[0]) || (ctx.origin + '/sitemap.xml');
  const status = Number(res.statusCode || 0);
  const body = typeof res.data === 'string' ? res.data : (typeof res.body === 'string' ? res.body : '');
  const locs = re => [...body.matchAll(re)].map(m => m[1].trim().replace(/&amp;/g, '&'));
  const base = { runId: ctx.runId, rootSitemapUrl: rootUrl, rootSitemapStatus: status, rootSitemapDeclared: !!(ctx.sitemaps && ctx.sitemaps.length) };
  if (status >= 200 && status < 300 && /<sitemapindex[\s>]/i.test(body)) {
    const children = locs(/<sitemap>[\s\S]*?<loc>([^<]+)<\/loc>/gi);
    const score = u => (/product/i.test(u) ? 0 : /categor|collection|product_cat/i.test(u) ? 1 : /page/i.test(u) ? 2 : /post/i.test(u) ? 3 : 4);
    const chosen = children.filter(u => !/\.gz(\?|$)/i.test(u)).sort((a, b) => score(a) - score(b)).slice(0, 5);
    if (chosen.length) return chosen.map(u => ({ ...base, rootSitemapType: 'index', childSitemapsInIndex: children.length, sitemapUrl: u }));
  }
  // Plain urlset, missing, or unreadable: fetch the root URL again in the next step and let the planner decide.
  const type = /<urlset[\s>]/i.test(body) ? 'urlset' : 'none';
  const out = [{ ...base, rootSitemapType: type, childSitemapsInIndex: 0, sitemapUrl: rootUrl }];
  // Sites that live in a subfolder (e.g. example.com/shop/ or user.github.io/project/) usually keep
  // their sitemap there too. If the root sitemap is missing, also try <folder>/sitemap.xml.
  const folder = ctx.targetUrl.replace(/[?#].*$/, '').replace(/[^\/]*$/, '');
  if (type === 'none' && folder !== ctx.origin + '/' && folder + 'sitemap.xml' !== rootUrl) {
    out.push({ ...base, rootSitemapType: 'folder', childSitemapsInIndex: 0, sitemapUrl: folder + 'sitemap.xml' });
  }
  return out;
}

const ctx = $('Parse robots.txt').first().json;
return sitemapTargets(ctx, $input.first().json).map(j => ({ json: j }));

// One row per audit run, with PageSpeed scores next to the SEO score for trend tracking.
const s = $input.all().map(i => i.json).find(r => r.recordType === 'summary');
let psi = [];
try { psi = $('PageSpeed Results').all().map(i => i.json); } catch (e) { psi = []; }
const score = k => { const r = psi.find(p => p.strategy === k && p.psiStatus === 'OK'); return r ? r.performanceScore : null; };
return [{ json: {
  runId: s.runId, auditTarget: s.auditTarget, auditedAt: s.auditedAt,
  pagesAudited: s.pagesAudited, pagesOk: s.pagesOk, pagesFailed: s.pagesFailed,
  pagesFromSitemap: s.pagesFromSitemap, sitemapUrlsFound: s.sitemapUrlsFound,
  findingsTotal: s.findingsTotal, high: s.high, medium: s.medium, low: s.low,
  seoHealthScore: s.seoHealthScore, mobileScore: score('mobile'), desktopScore: score('desktop'),
  psiStatus: psi.map(p => p.strategy + ':' + p.psiStatus).join(', '),
  topFindings: s.topFindings
} }];

// One row per finding. status starts as 'open' so fixes can be tracked later (M9).
// affectedUrls (space-separated) lets the fix tool know exactly which pages to change.
return $input.all().map(i => i.json).filter(r => r.recordType === 'finding').map(f => ({ json: {
  runId: f.runId, auditTarget: f.auditTarget, priorityRank: f.priorityRank, priority: f.priority,
  severity: f.severity, findingId: f.findingId, category: f.category, title: f.title,
  affectedPages: f.affectedPages, pagesAudited: f.pagesAudited,
  evidence: String(f.evidence).slice(0, 2000), recommendation: f.recommendation,
  reference: f.reference || '', status: 'open',
  affectedUrls: (f.affectedUrls || []).join(' ').slice(0, 4000)
} }));
